import {categories,validData,summary,csvCell,calculate} from './model.mjs';
const $=id=>document.getElementById(id),key='kotsukotsu-money-v1',colors=['#c88c90','#dfb58c','#a9b59a','#c3adcd','#9ebac1','#d4c18b','#c7beb4'],icons=['🍚','🧺','🚃','🎨','🏠','🌷','✧'];
let data={version:1,entries:[],budgets:{}},storageReady=true;try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(!validData(parsed))throw Error();data=parsed;}}catch{storageReady=false;}
const now=new Date(),localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let view=new Date(now.getFullYear(),now.getMonth(),1);const monthKey=()=>localDate(view).slice(0,7),yen=v=>'¥'+v.toLocaleString('ja-JP');let timer;function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(timer);const el=$('toast');timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function persist(next){if(!storageReady){toast('保存領域を読み込めません。ブラウザの設定を確認してください。');return false;}try{localStorage.setItem(key,JSON.stringify(next));data=next;return true;}catch{toast('保存できませんでした。ブラウザの空き容量をご確認ください。');return false;}}
function type(){return document.querySelector('input[name=type]:checked').value;}function options(){const s=$('category');s.replaceChildren(...categories[type()].map(c=>new Option(c,c)));}
function reset(){ $('entry-form').reset();$('edit-id').value='';$('date').value=localDate(now);$('save').textContent='＋ 記録を追加';$('cancel-edit').hidden=true;options();}
function render(){const m=monthKey(),s=summary(data.entries,m);$('month').textContent=`${view.getFullYear()}年 ${view.getMonth()+1}月`;$('balance').textContent=yen(s.balance);$('income').textContent=yen(s.income);$('expense').textContent=yen(s.expense);const budget=data.budgets[m];$('remaining').textContent=budget?`${s.expense>budget?'予算オーバー':'あと'} ${yen(Math.abs(budget-s.expense))}`:'未設定';$('budget-total').textContent=budget?`予算 ${yen(budget)}`:'予算を決めてみよう';$('budget-bar').style.width=budget?Math.min(s.expense/budget*100,100)+'%':'0%';$('budget-bar').style.background=s.expense>budget?'#c88c90':'#a5b197';$('budget-message').textContent=budget?(s.expense>budget?'来月に向けて、ゆっくり見直してみよう。':`予算の ${Math.round(s.expense/budget*100)}% を使っています。`):'無理のないペースで、こつこつと。';
const totals=categories.expense.map((c,i)=>({c,i,n:s.rows.filter(e=>e.type==='expense'&&e.category===c).reduce((a,e)=>a+e.amount,0)})).filter(x=>x.n).sort((a,b)=>b.n-a.n);let angle=0;const gradient=totals.map(x=>{const start=angle;angle+=x.n/s.expense*100;return `${colors[x.i]} ${start}% ${angle}%`;}).join(',');$('chart').innerHTML='<div class="donut"><div><small>今月の支出</small><strong></strong></div></div>';$('chart').firstChild.style.background=s.expense?`conic-gradient(${gradient})`:'#f4eee8';$('chart').querySelector('strong').textContent=yen(s.expense);$('categories').replaceChildren();if(!totals.length){const p=document.createElement('p');p.className='empty';p.textContent='記録すると、支出の内訳が見えてきます。';$('categories').append(p);}for(const t of totals){const row=document.createElement('div');row.className='category-row';row.innerHTML='<span class="dot"></span><span></span><strong></strong><small></small>';row.children[0].style.background=colors[t.i];row.children[1].textContent=t.c;row.children[2].textContent=yen(t.n);row.children[3].textContent=Math.round(t.n/s.expense*100)+'%';$('categories').append(row);}
const rows=s.rows.filter(e=>$('filter').value==='all'||e.type===$('filter').value).sort((a,b)=>b.date.localeCompare(a.date));$('count').textContent=rows.length+'件';$('transactions').replaceChildren();if(!rows.length){$('transactions').innerHTML='<div class="empty"><span>𖧷</span>まだ、きろくはありません。<br>今日のお金のこと、ひとつ書いてみよう。</div>';}
for(const e of rows){const row=document.createElement('div');row.className='transaction';row.innerHTML='<span class="tx-icon"></span><div class="tx-info"><strong></strong><small></small></div><span class="tx-amount"></span><div class="tx-actions"><button>編集</button><button>削除</button></div>';row.children[0].textContent=e.type==='income'?'🌱':icons[categories.expense.indexOf(e.category)];row.querySelector('strong').textContent=e.note||e.category;row.querySelector('small').textContent=`${e.date.slice(5).replace('-','/')} · ${e.category}${e.source?' · '+e.source:''}`;const a=row.querySelector('.tx-amount');a.textContent=(e.type==='income'?'+':'−')+yen(e.amount);a.classList.toggle('positive',e.type==='income');const buttons=row.querySelectorAll('button');buttons[0].setAttribute('aria-label',`${e.note||e.category}を編集`);buttons[1].setAttribute('aria-label',`${e.note||e.category}を削除`);buttons[0].onclick=()=>edit(e);buttons[1].onclick=()=>{if(confirm('この記録を削除しますか？')){if(persist({...data,entries:data.entries.filter(x=>x.id!==e.id)})){if($('edit-id').value===e.id)reset();render();toast('記録を削除しました');}}};$('transactions').append(row);}}
function edit(e){document.querySelector(`input[name=type][value=${e.type}]`).checked=true;options();$('edit-id').value=e.id;$('amount').value=e.amount;$('date').value=e.date;$('category').value=e.category;$('note').value=e.note;$('entry-source').value=e.source||'';$('save').textContent='変更を保存';$('cancel-edit').hidden=false;$('amount').focus();$('entry-form').scrollIntoView({behavior:'smooth',block:'center'});}
$('entry-form').onsubmit=e=>{e.preventDefault();const id=$('edit-id').value,entry={id:id||crypto.randomUUID(),amount:Number($('amount').value),type:type(),date:$('date').value,category:$('category').value,note:$('note').value.trim(),source:$('entry-source').value.trim()};const next={...data,entries:id?data.entries.map(x=>x.id===id?entry:x):[...data.entries,entry]};if(!validData(next)){toast('金額と日付を確認してください。');return;}if(persist(next)){view=new Date(Number(entry.date.slice(0,4)),Number(entry.date.slice(5,7))-1,1);reset();render();toast(id?'変更を保存しました':'ひとつ、記録できました ❀');}};
document.querySelectorAll('input[name=type]').forEach(r=>r.onchange=options);$('cancel-edit').onclick=reset;$('prev').onclick=()=>{view.setMonth(view.getMonth()-1);render();};$('next').onclick=()=>{view.setMonth(view.getMonth()+1);render();};$('today').onclick=()=>{view=new Date(now.getFullYear(),now.getMonth(),1);render();};$('filter').onchange=render;
$('budget-edit').onclick=()=>{$('budget-input').value=data.budgets[monthKey()]||'';$('budget-dialog').showModal();};$('budget-cancel').onclick=()=>$('budget-dialog').close();$('budget-form').onsubmit=e=>{e.preventDefault();const next={...data,budgets:{...data.budgets,[monthKey()]:Number($('budget-input').value)}};if(validData(next)&&persist(next)){$('budget-dialog').close();render();toast('予算を設定しました');}};
function download(content,name,mime){const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>{const rows=summary(data.entries,monthKey()).rows.sort((a,b)=>a.date.localeCompare(b.date));const table=[['日付','種類','カテゴリ','金額（円）','メモ','口座・カード名'],...rows.map(e=>[e.date,e.type==='expense'?'支出':'収入',e.category,e.amount,e.note,e.source||''])];download('\ufeff'+table.map(row=>row.map(csvCell).join(',')).join('\r\n'),`こつこつ-${monthKey()}.csv`,'text/csv;charset=utf-8');toast('今月の記録をCSVで保存しました');};$('backup').onclick=()=>download(JSON.stringify(data,null,2),`こつこつ-backup-${localDate(new Date())}.json`,'application/json');$('restore').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error();const next=JSON.parse(await file.text());if(!validData(next))throw Error();if(confirm(`現在の記録をバックアップの${next.entries.length}件で置き換えます。よろしいですか？`)&&persist(next)){reset();render();toast('バックアップを復元しました');}}catch{toast('有効なバックアップファイルを選んでください。');}finally{e.target.value='';}};
window.addEventListener('storage',e=>{if(e.key===key){try{const next=e.newValue?JSON.parse(e.newValue):{version:1,entries:[],budgets:{}};if(validData(next)){data=next;reset();render();}}catch{toast('別タブの更新を読み込めませんでした');}}});reset();render();if(!storageReady)toast('保存領域を読み込めません。ブラウザの設定を確認してください。');

let calcValue=0;
function updateCalc(){try{calcValue=$('calc-expression').value.trim()?calculate($('calc-expression').value):0;$('calc-result').textContent=calcValue.toLocaleString('ja-JP',{maximumFractionDigits:8});$('calc-use').disabled=!Number.isSafeInteger(calcValue)||calcValue<=0||calcValue>999999999;}catch(e){calcValue=null;$('calc-result').textContent=e.message;$('calc-use').disabled=true;}}
$('calculator-open').onclick=()=>{$('calc-expression').value=$('amount').value;updateCalc();$('calculator').showModal();};$('calc-close').onclick=()=>$('calculator').close();$('calc-expression').oninput=updateCalc;
for(const key of ['C','(',')','⌫','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','=','+']){const b=document.createElement('button');b.textContent=key;if(['÷','×','−','+','='].includes(key))b.className='operator';b.onclick=()=>{const f=$('calc-expression');if(key==='C')f.value='';else if(key==='⌫')f.value=f.value.slice(0,-1);else if(key==='='){try{f.value=String(calculate(f.value));}catch(e){toast(e.message);}}else f.value+=key;updateCalc();};$('calc-keys').append(b);}
$('calc-use').onclick=()=>{if(Number.isSafeInteger(calcValue)&&calcValue>0){$('amount').value=calcValue;$('calculator').close();$('amount').focus();toast('計算結果を金額に入力しました');}};

import {setupImporter} from './import-ui.mjs';
setupImporter({getData:()=>data,persist,onImported:date=>{view=new Date(Number(date.slice(0,4)),Number(date.slice(5,7))-1,1);render();},toast});

$('calc-expression').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();try{$('calc-expression').value=String(calculate($('calc-expression').value));updateCalc();}catch(error){toast(error.message);}}});

import {setupReceipts} from './receipt-ui.mjs';
setupReceipts({getData:()=>data,persist,onImported:date=>{view=new Date(Number(date.slice(0,4)),Number(date.slice(5,7))-1,1);render();},toast});
